import{_ as a,o as t,c as s,ae as i}from"./chunks/framework.BCZ_EjGL.js";const u=JSON.parse('{"title":"Markdown Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1.0.0/markdown.md","filePath":"v1.0.0/markdown.md"}'),o={name:"v1.0.0/markdown.md"};function n(l,e,r,d,h,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="markdown-guide" tabindex="-1">Markdown Guide <a class="header-anchor" href="#markdown-guide" aria-label="Permalink to &quot;Markdown Guide&quot;">​</a></h1><p>AskBot AI supports a subset of Markdown to help you create rich, interactive, and visually appealing bot responses. This guide covers all the supported syntax and provides examples for each.</p><h2 id="_1-text-formatting" tabindex="-1">1. Text Formatting <a class="header-anchor" href="#_1-text-formatting" aria-label="Permalink to &quot;1. Text Formatting&quot;">​</a></h2><h3 id="bold" tabindex="-1">Bold <a class="header-anchor" href="#bold" aria-label="Permalink to &quot;Bold&quot;">​</a></h3><p>Use double asterisks to make text bold.</p><ul><li><strong>Syntax</strong>: <code>**Your Text**</code></li><li><strong>Output</strong>: <strong>Your Text</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Italic formatting (single asterisk) is currently not supported by the bot&#39;s custom parser.</p></div><hr><h2 id="_2-links" tabindex="-1">2. Links <a class="header-anchor" href="#_2-links" aria-label="Permalink to &quot;2. Links&quot;">​</a></h2><p>Create clickable links that open in a new tab.</p><ul><li><strong>Syntax</strong>: <code>[Link Text](https://example.com)</code></li><li><strong>Output</strong>: <a href="https://example.com" target="_blank" rel="noreferrer">Link Text</a></li></ul><hr><h2 id="_3-media-images-videos" tabindex="-1">3. Media (Images &amp; Videos) <a class="header-anchor" href="#_3-media-images-videos" aria-label="Permalink to &quot;3. Media (Images &amp; Videos)&quot;">​</a></h2><h3 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h3><p>Embed images directly in the chat.</p><ul><li><strong>Syntax</strong>: <code>![Alt Text](https://path/to/image.png)</code></li></ul><h3 id="videos" tabindex="-1">Videos <a class="header-anchor" href="#videos" aria-label="Permalink to &quot;Videos&quot;">​</a></h3><p>You can embed MP4/WebM videos or link to YouTube/Vimeo.</p><ul><li><strong>Direct Video</strong>: <code>![Video](https://path/to/video.mp4)</code></li><li><strong>YouTube</strong>: <code>![YouTube](https://www.youtube.com/watch?v=dQw4w9WgXcQ)</code></li><li><strong>Vimeo</strong>: <code>![Vimeo](https://vimeo.com/123456789)</code></li></ul><h3 id="custom-video-tag" tabindex="-1">Custom Video Tag <a class="header-anchor" href="#custom-video-tag" aria-label="Permalink to &quot;Custom Video Tag&quot;">​</a></h3><p>A shorter syntax specifically for videos.</p><ul><li><strong>Syntax</strong>: <code>[v](https://path/to/video.mp4)</code></li></ul><hr><h2 id="_4-lists" tabindex="-1">4. Lists <a class="header-anchor" href="#_4-lists" aria-label="Permalink to &quot;4. Lists&quot;">​</a></h2><p>Create unordered lists using asterisks or hyphens.</p><ul><li><strong>Syntax</strong>:<div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Item 1</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Item 2</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Item 3</span></span></code></pre></div></li></ul><hr><h2 id="_5-tables" tabindex="-1">5. Tables <a class="header-anchor" href="#_5-tables" aria-label="Permalink to &quot;5. Tables&quot;">​</a></h2><p>Organize data into structured tables. Use the pipe <code>|</code> character to separate columns.</p><ul><li><strong>Syntax</strong>:<div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Month | Revenue | Growth |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| :--- | :--- | :--- |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Jan | $10k | +5% |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Feb | $12k | +20% |</span></span></code></pre></div></li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The separator line (<code>| :--- |</code>) is optional but recommended for better readability in your source configuration.</p></div><hr><h2 id="_6-headings" tabindex="-1">6. Headings <a class="header-anchor" href="#_6-headings" aria-label="Permalink to &quot;6. Headings&quot;">​</a></h2><p>Use multiple hash symbols to create headings.</p><ul><li><strong>Syntax</strong>: <code>### Heading Level 3</code></li><li><strong>Output</strong>:</li></ul><h3 id="heading-level-3" tabindex="-1">Heading Level 3 <a class="header-anchor" href="#heading-level-3" aria-label="Permalink to &quot;Heading Level 3&quot;">​</a></h3><hr><h2 id="_7-newlines" tabindex="-1">7. Newlines <a class="header-anchor" href="#_7-newlines" aria-label="Permalink to &quot;7. Newlines&quot;">​</a></h2><p>Simple line breaks in your text will be rendered as new lines in the chat bot. No special syntax is required.</p>`,39)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
